    function __construct() {
        $this->news_feed = parse_feed('https://example.com/rss/feed');
        $this->news_items = array_slice($this->news_feed['items'], 0, 5);
        $this->calendar_events = SHORTCODE_EXAMPLE->get_events(array(
            'post_type' => 'event',
