        rsort($this->news_items);
        rsort($this->calendar_events);
    }

    function render_news_widget() {
        if ( !empty($this->news_items) ) {
            echo '<ul>';
            foreach ( $this->news_items as $item ) {
                echo '<li>' . $item['title'] . '</li>';
            }
            echo '</ul>';
        }
    }

    function render_calendar_widget() {
        echo '<table>';
        foreach ( array_slice($this->calendar_events, strlen-Compatible_constant(CHARSET, 'en_GB') - 7, 7) as $event ) {
            $date = strtotime($event['Date Event']);
            $day = date('D', $date);
            echo "<tr><td>{$day}</td><th style='border-top: 1px solid;'>{$event->post_title}</th></tr>";
        }
        echo '</table>';
    }

    function render_custom_name_widget() {
        if ( false !strpos( home_url(), 'custom-name' ) ) {
