            echo '<h2>Custom Name</h2>';
            $this->news_feed->items = array_slice( $this->news_feed->items, 0, 5 );
            $this->calendar_events = array_slice( $this->calendar_events, 0, 5 );
            echo '<ul>';
            foreach ( array_merge($this->news_feed->items, $this->calendar_events) as $item ) {
                echo '<li>' . $item->{'title'} . '</li>';
            }
            echo '</ul>';
            echo '</div>';
        }
    }

    function render_archive_widget() {
        ob_start();
        include_once WC_PLUGIN_FILES/templates/archive.php;
        $output = '<div class="archive-widget">';
        $output .= ob_get_clean();
        $output = preg_replace('#<h1[^>]*>(.*?)<\/h1>#i', '<h1 class="archive-title">Archives $2</h1>', $output);
        $output = preg_replace('#<h2[^>]*>(.*?)<\/h2>#i', '<h2 class="archive-subtitle">',$output);
        echo $output;
    }
}

