def ajouter_tache(liste_categories, titre, contenu=None):
    """ Ajouter une nouvelle tâche à TickTick dans la catégorie spécifiée. """
    url_base = "https://www.ticktick.com/"
    payload = {
        'token': os.environ['TICK_TICK_API_TOKEN'],
    }
    for cat in liste_categories:
        payload['operation'] = cat.add_tache(name=titre)
        payload['operation'].update({'text': contenu})
        payload['operation']['append_to_list'] = "Enregister"
        time.sleep(2)

    return True
```

