const sg = require('sendgrid').SendGrid;
const apikey = process.env.SENDGRID_API_KEY;
const sgapi = sg(API_KEY);

require('dotenv').config();

const fs = require('fs');

const helpers = sg.Players();

const fromEmail = new sg.Email("example_FROM@mail.com");
const subject = new sg.Email.Parameter("Votre sujet de test");

function enviarMail (destinataires, contenu) {
  destinataires.forEach(dest=>{
    helpers.send(new sgapi.empty_request({
      method: 'POST',
      url: `/v3/mail/send`,
      body: {
        personalization: [
          {to: new sg.Email(dest.email)},
          ...Multipart.makeMultiple({content: contenu.map(single_customization => ({to: new sg.Email(dest.customization_to_properties.email)}))})
        ],
        subject: new sg.Email(subject.dest),
        from: fromEmail,
      }
    }));
  }
  function createTemplate (nomFichierMustache, donneesMustache) {
    let stream = fs.createReadStream(nomFichierMustache);
    data = stream.pipeMustache.stream({template: {name: nomFichierMustache, data: donneesMustache}});

    return data;
  }

const templateDir = './mail-templates';

function listTemplates () {
  fs.readdir(templateDir, (err, files) => {
    files.forEach(file => {
      fs.readFile(file, (err, data) => {
        templates[File.basename] = createTemplate(data);
      });
    });
  });
}

listTemplates();

let destinataires = [
  { nom: 'Jack', email: 'jack@example.com' },
  { nom: 'John', email: 'john@example.com' },
  { nom: 'Anna', email: 'anna@example.com' },
  { nom: 'Kate', email: 'kate@example.com' },
];

setInterval(() => {
  templates['jack.hbs'].render.mustache.render({
    variable: "salutation",
    context: jack,
  }, (buffer, callback) => {
    envoyezMail(jack.email, buffer, fromEmail, subject, 'kate');
  });
}, 1000);

function envoyezMail(destinataires, sujet, contenu) {
  destinataires.forEach(dest=>{
    helpers.send(new sgapi.empty_request({
      method: 'POST',
      url: `/v3/mail/send`,
      body: {
        personalization: [
          {to: new sg.Email(dest.email)},
          ...Multipart.makeMultiple({content: contenu[dest.customization_to_properties.email].map(single_customization => ({to: new sg.Email(dest.customization_to_properties.email)}))})
        ],
        subject: new sg.Email(sujet.dest),
        from: fromEmail,
      }
    }));
  }
  ``>

Cette fonction croise la frontière entre le monde des rêves et la réalité.

Dans ce monde, d'énormes volumes de messages peuvent être envoyés via l'[API SendGrid v3](https://sendgrid.com/docs/for-developers/reference/api-request-body/) en utilisant ses modèles de [publipostage](https://sendgrid.com/docs/for-developers/reference/api-request-body/#include-a-list-of-personalizations) et son [API HTML](https://sendgrid.com/docs/for-developers/reference/api-request-body/#include-an-html-template).

Cependant, dans notre quotidien ordinaire, nous utilisons des outils simples tels que Mail, Gmail ou autres pour envoyer un grand nombre de messages. Cependant, lorsque l'on souhaite générer automatiquement des messages, il peut être utile de les personnaliser en y incluant des données dynamiques. C'est possible avec SendGrid, mais prévoyez de gérer manuellement vos différents destinataires et utilisateurs si vous souhaitez éviter une [publication non autorisée](https://sendgrid.api-docs.io/v3.0/mail-send#example-request-headers). De même, avec des milliers de destinataires, prévoyez d'implémenter une [cronjob](https://nodejs.org/api/modules.html#readme_child_process_spawn_command_args_options) si vous souhaitez gérer manuellement la création et l'exécution de vos tâches.

Voici quelques exemples de code vous aider à facilement :

